package org.example.issuetracker.issue;

import org.example.issuetracker.user.*;
import org.springframework.data.domain.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class IssueService {
    private final IssueRepository issues;
    private final AppUserRepository users;

    public IssueService(IssueRepository issues, AppUserRepository users) {
        this.issues = issues;
        this.users = users;
    }

    @Transactional
    public IssueResponse create(CreateIssueRequest request, Authentication authentication) {
        AppUser creator = users.findByUsername(authentication.getName()).orElseThrow();
        Issue issue = new Issue(request.title().trim(), request.description().trim(), request.priority(), creator);
        return toResponse(issues.save(issue));
    }

    @Transactional(readOnly = true)
    public Page<IssueResponse> list(IssueStatus status, Pageable pageable) {
        Page<Issue> page = status == null
            ? issues.findAll(pageable)
            : issues.findByStatus(status, pageable);
        return page.map(this::toResponse);
    }

    @Transactional
    public IssueResponse changeStatus(long id, IssueStatus status) {
        Issue issue = issues.findById(id).orElseThrow(() -> new IssueNotFoundException(id));
        issue.changeStatus(status);
        return toResponse(issue);
    }

    @Transactional
    public void delete(long id) {
        if (!issues.existsById(id)) {
            throw new IssueNotFoundException(id);
        }
        issues.deleteById(id);
    }

    private IssueResponse toResponse(Issue issue) {
        return new IssueResponse(
            issue.getId(), issue.getTitle(), issue.getDescription(),
            issue.getPriority(), issue.getStatus(), issue.getCreatedAt(),
            issue.getCreatedBy().getUsername()
        );
    }
}

