package org.example.issuetracker.web;

import org.example.issuetracker.issue.IssueNotFoundException;
import org.springframework.http.*;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.*;
import java.util.stream.Collectors;

@RestControllerAdvice
public class ApiExceptionHandler {
    @ExceptionHandler(IssueNotFoundException.class)
    ResponseEntity<ProblemDetail> notFound(IssueNotFoundException ex) {
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.NOT_FOUND);
        pd.setDetail(ex.getMessage());
        return ResponseEntity.status(HttpStatus.NOT_FOUND).body(pd);
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    ResponseEntity<ProblemDetail> validation(MethodArgumentNotValidException ex) {
        String detail = ex.getBindingResult().getFieldErrors().stream()
            .map(e -> e.getField() + ": " + e.getDefaultMessage())
            .collect(Collectors.joining("; "));
        ProblemDetail pd = ProblemDetail.forStatus(HttpStatus.BAD_REQUEST);
        pd.setDetail(detail);
        return ResponseEntity.badRequest().body(pd);
    }
}

package org.example.issuetracker.security;

import org.springframework.context.annotation.*;
import org.springframework.security.config.annotation.method.configuration.EnableMethodSecurity;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;

@Configuration
@EnableWebSecurity
@EnableMethodSecurity
public class SecurityConfig {
    @Bean
    PasswordEncoder passwordEncoder() {
        return Argon2PasswordEncoder.defaultsForSpringSecurity_v5_8();
    }

    @Bean
    SecurityFilterChain securityFilterChain(HttpSecurity http) throws Exception {
        http
            .authorizeHttpRequests(a -> a
                .requestMatchers("/css/**", "/login", "/actuator/health").permitAll()
                .anyRequest().authenticated()
            )
            .formLogin(f -> f.loginPage("/login").defaultSuccessUrl("/issues", true))
            .logout(l -> l.logoutSuccessUrl("/login?logout"));
        return http.build();
    }
}

package org.example.issuetracker.config;

import org.example.issuetracker.user.*;
import org.springframework.boot.CommandLineRunner;
import org.springframework.context.annotation.*;
import org.springframework.security.crypto.password.PasswordEncoder;

@Configuration
public class DataInitializer {
    @Bean
    CommandLineRunner seedUsers(AppUserRepository users, PasswordEncoder encoder) {
        return args -> {
            createIfAbsent(users, encoder, "admin", UserRole.ADMIN, "APP_ADMIN_PASSWORD");
            createIfAbsent(users, encoder, "user", UserRole.USER, "APP_USER_PASSWORD");
        };
    }

    private void createIfAbsent(
        AppUserRepository users,
        PasswordEncoder encoder,
        String username,
        UserRole role,
        String envName
    ) {
        if (users.findByUsername(username).isPresent()) return;
        String password = System.getenv(envName);
        if (password == null || password.isBlank()) {
            throw new IllegalStateException(envName + " is required");
        }
        users.save(new AppUser(username, encoder.encode(password), role));
    }
}

